import{_ as n,o as t,c as i,a3 as r}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"ATLAS Icon Studio","description":"Iconsets mit ATLAS Icon Studio verwalten, importieren, löschen und in Home Assistant speichern.","frontmatter":{"title":"ATLAS Icon Studio","description":"Iconsets mit ATLAS Icon Studio verwalten, importieren, löschen und in Home Assistant speichern."},"headers":[],"relativePath":"projects/atlas-plugins/icon-studio.md","filePath":"projects/atlas-plugins/icon-studio.md","lastUpdated":1792862520000}'),s={name:"projects/atlas-plugins/icon-studio.md"};function a(o,e,l,d,u,c){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="atlas-icon-studio" tabindex="-1">ATLAS Icon Studio <a class="header-anchor" href="#atlas-icon-studio" aria-label="Permalink to &quot;ATLAS Icon Studio&quot;">​</a></h1><p>ATLAS Icon Studio ist ein separat installiertes Plugin zum Erstellen und Verwalten von Home-Assistant-Iconsets mit dem Präfix <code>atlas:</code>. Version 0.1.15 unterstützt große Sammlungen ohne feste Icon-Anzahlgrenze; die Liste rendert jeweils nur 24 Einträge.</p><h2 id="icons-verwalten" tabindex="-1">Icons verwalten <a class="header-anchor" href="#icons-verwalten" aria-label="Permalink to &quot;Icons verwalten&quot;">​</a></h2><p>Aktueller Plugin-Stand: <strong>0.1.17</strong>. Diese Version korrigiert den fehlenden Validator-Import beim Anlegen von Zeichnungstext. Version 0.1.16 behob zuvor einen Startfehler beim Exportformat-Selektor. Speicherformate bleiben unverändert.</p><p>Die Sammlung liegt im browserlokalen IndexedDB-Speicher. Ältere lokale Daten werden übernommen; vor einem Browser-/Adresswechsel die Sammlung als JSON sichern.</p><h2 id="zeichnen-und-bildvorschau" tabindex="-1">Zeichnen und Bildvorschau <a class="header-anchor" href="#zeichnen-und-bildvorschau" aria-label="Permalink to &quot;Zeichnen und Bildvorschau&quot;">​</a></h2><p>Ein separater Zeichenbereich unterstützt farbige SVGs mit Formen, Freihand und Text, Ebenenreihenfolge sowie bis zu zehn Rückgängig-/Wiederholen-Schritte. „Speichern unter“ exportiert SVG, PNG oder WebP, optional mit transparentem Hintergrund. Rasterbilder lassen sich anzeigen und optional vektorisieren; sie werden nicht direkt zu <code>atlas:</code>-Icons. Das HA-Iconset benötigt SVG-Pfade. File Studio kann unterstützte Bilder auf demselben ATLAS-Server direkt an Icon Studio übergeben. Downloads werden nicht automatisch nach HA kopiert.</p><h2 id="sammlung-bearbeiten" tabindex="-1">Sammlung bearbeiten <a class="header-anchor" href="#sammlung-bearbeiten" aria-label="Permalink to &quot;Sammlung bearbeiten&quot;">​</a></h2><p>Wähle ein Icon in der Sammlung aus und nutze <strong>Icon löschen</strong>, um es zu entfernen. Danach wird automatisch das nächste löschbare Icon ausgewählt. So lassen sich mehrere Icons hintereinander löschen, ohne nach jedem Schritt erneut ein Icon auswählen zu müssen. Das Referenz-Icon <code>atlas:home</code> ist geschützt und kann nicht gelöscht werden. Mindestens ein Icon bleibt in der Sammlung.</p><p>Suche, Tastaturnavigation und Export beziehen sich auf die gesamte Sammlung, auch wenn gerade nur ein kleiner Ausschnitt sichtbar ist. Sammlungen können als JSON gesichert und wieder eingelesen werden; Namenskonflikte lassen sich ersetzen, überspringen oder automatisch umbenennen.</p><h2 id="home-assistant" tabindex="-1">Home Assistant <a class="header-anchor" href="#home-assistant" aria-label="Permalink to &quot;Home Assistant&quot;">​</a></h2><p>Iconsets können lokal als <code>atlas-iconset.js</code> exportiert oder direkt über File Studio aus <code>/config/www/atlas-iconset.js</code> eingelesen werden. Beim Speichern kann die vorhandene Datei ersetzt werden; File Studio legt dabei eine Sicherung an. Alternativ erstellt Icon Studio eine neue nummerierte Datei und zeigt den <code>/local/...</code>-Ressourcenpfad an, der in Home Assistant registriert werden muss. Für direkten Zugriff muss <code>/config/www</code> in File Studio freigegeben sein.</p><p>Weitere Details zu Installation, Formaten und Dateipfaden stehen in der <a href="https://github.com/rockbaer2007/atlas-icon-studio-plugin#readme" target="_blank" rel="noreferrer">Plugin-README</a>.</p><h2 id="sichere-plugin-wiederherstellung" tabindex="-1">Sichere Plugin-Wiederherstellung <a class="header-anchor" href="#sichere-plugin-wiederherstellung" aria-label="Permalink to &quot;Sichere Plugin-Wiederherstellung&quot;">​</a></h2><p>Vorher die Sammlung als JSON sichern, das Iconset exportieren und Zeichnungen separat als SVG speichern. In <strong>Administration → Plugin-Manager → Icon Studio → Wiederherstellen</strong> eine Sicherung auswählen, Version und Kompatibilität prüfen und <strong>Sichern und übernehmen</strong> ausführen. Die aktuelle Plugin-Version wird dabei ebenfalls gesichert. <strong>Abbrechen</strong> lässt die Installation unverändert.</p><div class="info custom-block"><p class="custom-block-title">Isoliert geprüft am 16.10.2026</p><p>Mit ATLAS 0.1.312 wurden der Wechsel <strong>0.1.16 → 0.1.17</strong> und die Wiederherstellung <strong>0.1.17 → 0.1.16 → gesicherte 0.1.17</strong> einschließlich App-Neustart geprüft. Alle zwölf Paketdateien waren versionsgenau. Die Sammlung mit 131 Icons und eine Zeichnung mit zwei Textobjekten blieben bei gleicher Browseradresse und gleichem Profil erhalten. JSON-, Iconset-JavaScript- und SVG-Exporte waren danach bytegleich. Neue Texteingabe, Duplizieren und Rückgängig funktionierten. Testdateien, bestehendes Iconset, Projekt, anderes Plugin, Papierkorb und Historie blieben erhalten. Vorher wurden Repositories, Serverdaten und Browser-Exporte gesichert. <strong>Pi 5 und Proxmox wurden weder abgefragt noch verändert.</strong> Datenformat-Migrationen sind damit nicht geprüft.</p></div><div class="info custom-block"><p class="custom-block-title">Auf Pi 5 und Proxmox geprüft am 16.10.2026</p><p>Nach neuen lokalen HA-Sicherungen, PC-Dateikopien und Browser-Exporten wurde <strong>0.1.16 → 0.1.17 → ursprüngliche 0.1.16 → 0.1.17</strong> über die Administration geprüft. Alle zwölf Paketdateien stimmen; Einstellungen, vorhandene Dateien, sechs aktive Plugins, Projekt, Papierkorb und Historie bleiben erhalten. ATLAS 0.1.312 und HA 2026.10.1 benötigten keinen Neustart. Beide Systeme enden mit Icon Studio 0.1.17. Bei einer abgewiesenen veralteten Update-Vorschau nach Wiederherstellung die Administration neu laden und das Update erneut wählen. Direkter Zugang und HA-Ingress wurden je Host geprüft: jeweils drei Referenzicons und ein leerer Zeichnungsentwurf. Sammlungs-JSON bleibt bytegleich, der Entwurf nach Neuladen unverändert. Text anlegen und rückgängig machen funktioniert. Größere Sammlungen und gefüllte Zeichnungen wurden im isolierten Test geprüft.</p></div><p>Die Paket-Wiederherstellung stellt keine gelöschten Browserdaten wieder her. IndexedDB und lokaler Zeichnungsentwurf gehören zum Browserprofil und zum Ursprung aus Protokoll, Host und Port. Eine HA-/Serversicherung enthält diese Browserdaten nicht. Sammlungs-JSON und Iconset-JavaScript enthalten keine farbige Zeichnung; eine exportierte SVG ist kein vollständiges Entwurfs-/Undo-Backup. Formen und Dateiname des aktuellen Entwurfs bleiben lokal erhalten; Werkzeugauswahl, Suche und Rückgängig-/Wiederholen-Verlauf sind sitzungsbezogen.</p>',18)])])}const m=n(s,[["render",a]]);export{g as __pageData,m as default};
